// The Google Sheets node emits one item per row plus a row_number field.
// Keep the FIRST row whose Status column is empty — row_number lets the
// update node at the end mark exactly this row as done.
const rows = $input.all().map((i) => i.json);
const isEmpty = (v) => v === undefined || v === null || String(v).trim() === '';
const row = rows.find((r) => isEmpty(r.Status));
if (!row) {
  return [{ json: { found: false, checked: rows.length } }];
}
const quote = String(row.Quote || '').trim();
const author = String(row.Author || '').trim();
if (!quote || !author) {
  throw new Error('Row ' + row.row_number + ' is missing Quote or Author. Fill both columns, or put anything in Status to skip the row.');
}
return [{
  json: {
    found: true,
    quote,
    author,
    authorNote: String(row.AuthorNote || '').trim(),
    rowNumber: row.row_number,
    checked: rows.length,
  },
}];

// Every row already has a Status value, so there is nothing to render today.
// This is a normal, successful outcome — not an error.
const picked = $('Pick next quote').first().json;
return [{
  json: {
    rendered: false,
    reason: 'No row with an empty Status column. Add fresh quote rows to the sheet.',
    rowsChecked: picked.checked,
  },
}];

// === buildProject — identical to the frame-reviewed standalone builder ===
function buildProject(config, data) {
  const cfg = config || {};
  const clean = (v) => String(v == null ? '' : v).replace(/\s+/g, ' ').trim();
  const quote = clean(data.quote);
  const author = clean(data.author);
  const authorNote = clean(data.authorNote);
  if (!quote) throw new Error('The sheet row has no Quote text.');
  if (!author) throw new Error('The sheet row has no Author.');

  const channelName = clean(cfg.channelName) || '@yourchannel';
  const ctaText = clean(cfg.ctaText) || 'Follow for more';
  const quoteFont = clean(cfg.quoteFont) || 'Playfair Display';
  const uiFont = clean(cfg.uiFont) || 'Inter';
  const paper = clean(cfg.paperColor) || '#F0ECE3';
  const muted = clean(cfg.mutedColor) || '#B9B4A6';
  const ink = clean(cfg.inkColor) || '#14181A';

  const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
  const round = (n) => Math.round(n * 100) / 100;

  // ---- daily rotation pool ------------------------------------------------
  // Every URL verified reachable and probed (dimensions/duration/size) when
  // this template was authored. `videoSeconds` is the source clip length: the
  // quote scene must never outlast its background. `overlay` darkens the clip
  // so the paper-coloured text always has contrast — brighter clips get more.
  const MUSIC_CALM = 'https://cdn.pixabay.com/audio/2025/04/21/audio_ed6f0ed574.mp3'; // 48.6s, 1.5 MB
  const MUSIC_WARM = 'https://cdn.pixabay.com/audio/2025/03/19/audio_56ae1dae5f.mp3'; // 115.5s, 3.7 MB
  const POOL = [
    { label: 'mist-forest', video: 'https://videos.pexels.com/video-files/30149713/12928657_1080_1920_60fps.mp4', videoSeconds: 15.0, music: MUSIC_CALM, overlay: 0.5 },
    { label: 'ember-ink', video: 'https://videos.pexels.com/video-files/15168374/15168374-hd_1080_1920_24fps.mp4', videoSeconds: 38.9, music: MUSIC_WARM, overlay: 0.55 },
    { label: 'rain-window', video: 'https://videos.pexels.com/video-files/19802056/19802056-uhd_1440_2560_30fps.mp4', videoSeconds: 50.7, music: MUSIC_CALM, overlay: 0.45 },
    { label: 'cloud-sea', video: 'https://videos.pexels.com/video-files/32634790/13916180_1080_1920_25fps.mp4', videoSeconds: 11.0, music: MUSIC_WARM, overlay: 0.62 },
    { label: 'calm-shore', video: 'https://videos.pexels.com/video-files/28197979/12324927_1080_1920_60fps.mp4', videoSeconds: 10.4, music: MUSIC_CALM, overlay: 0.62 },
  ];

  const when = data.date ? new Date(data.date) : new Date();
  const dayOfYear = Math.floor((Date.UTC(when.getUTCFullYear(), when.getUTCMonth(), when.getUTCDate()) - Date.UTC(when.getUTCFullYear(), 0, 0)) / 86400000);
  const overrideIdx = Number(cfg.poolIndexOverride);
  const poolIndex = Number.isInteger(overrideIdx) && overrideIdx >= 0 ? overrideIdx % POOL.length : dayOfYear % POOL.length;
  const entry = POOL[poolIndex];

  const bgVideo = clean(cfg.backgroundVideoOverride) || entry.video;
  const musicUrl = clean(cfg.musicUrlOverride) || entry.music;
  // An override video has an unknown length, so never let the quote scene run
  // past the shortest clip in the pool.
  const bgSeconds = clean(cfg.backgroundVideoOverride) ? 10.4 : entry.videoSeconds;

  // ---- adaptive type ------------------------------------------------------
  // Greedy word-wrap estimate calibrated against the rendered source example
  // ("Almost everything will work" = 27 chars exactly fills 840px at 62px, so
  // the average glyph runs ~0.50em in Playfair italic).
  const wrapLines = (text, fontPx, boxPx, avgEm) => {
    const perLine = Math.max(6, Math.floor(boxPx / (fontPx * avgEm)));
    let lines = 1;
    let used = 0;
    for (const w of String(text).split(' ')) {
      const need = used === 0 ? w.length : used + 1 + w.length;
      if (need <= perLine) { used = need; continue; }
      lines += 1;
      used = Math.min(w.length, perLine);
    }
    return lines;
  };

  const qLen = quote.length;
  const quoteSize = qLen <= 90 ? 62 : qLen <= 140 ? 54 : qLen <= 180 ? 48 : 42;
  const quoteLines = wrapLines(quote, quoteSize, 840, 0.5);
  const quoteBlockH = Math.round(quoteLines * quoteSize * 1.35);
  // Keep the block visually centred where the source design places it, but
  // never above the big quote glyph.
  const quoteY = Math.max(600, Math.min(700, Math.round(800 - quoteBlockH / 2)));

  // Reading-time scene length: never past the background clip.
  const quoteSeconds = round(Math.min(Math.max(7, 3.5 + qLen * 0.03), 9.8, bgSeconds - 0.4));
  const cardSeconds = 4.6;

  const nameSize = author.length <= 20 ? 56 : author.length <= 30 ? 46 : 40;
  const nameLines = wrapLines(author, nameSize, 860, 0.55);
  const noteY = Math.round(850 + nameLines * nameSize * 1.25 + 30);
  const noteLines = authorNote ? wrapLines(authorNote, 27, 800, 0.62 + 2 / 27) : 0;
  const ctaY = Math.max(1160, noteY + noteLines * 40 + 110);

  // ---- scenes -------------------------------------------------------------
  const s1 = {
    id: 'quote',
    duration: quoteSeconds,
    backgroundColor: '#1B1E22',
    transition: 'fade',
    transitionId: 'author',
    transitionDuration: 0.8,
    visuals: [
      { type: 'VIDEO', src: bgVideo, width: 1080, height: 1920, position: 'center-center', resize: 'cover', volume: 0, track: 0, enterBegin: 0, exitEnd: quoteSeconds },
      {
        type: 'SVG', width: 1080, height: 1920, track: 1, enterBegin: 0, exitEnd: quoteSeconds,
        svg: "<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'><rect width='1080' height='1920' fill='rgba(20,24,26," + entry.overlay + ")'/><rect x='70' y='70' width='940' height='1780' fill='none' stroke='rgba(240,236,227,0.35)' stroke-width='1'/><text x='150' y='560' font-family='Georgia' font-size='220' fill='rgba(240,236,227,0.55)'>&#8220;</text><path d='M420 1480 H660' stroke='rgba(240,236,227,0.6)' stroke-width='1.5'/></svg>",
      },
      {
        type: 'TEXT', x: 540, y: 170, anchor: 'top-center', track: 2, enterBegin: 0.3, enterEnd: 0.9, enterAnimation: 'fade', exitEnd: quoteSeconds,
        style: { fontFamily: uiFont },
        html: "<div style=\"text-align:center; color:" + muted + "; font-size:23px; font-weight:600; letter-spacing:7px; text-shadow:0 2px 14px rgba(20,24,26,0.75);\">" + esc(channelName) + '</div>',
      },
      {
        type: 'TEXT', x: 540, y: quoteY, width: 840, anchor: 'top-center', track: 3, enterBegin: 0.7, enterEnd: 1.5, enterAnimation: 'smoothup', exitEnd: quoteSeconds,
        style: { fontFamily: quoteFont },
        html: "<div style=\"text-align:center; color:" + paper + '; font-size:' + quoteSize + "px; line-height:1.35; font-style:italic;\">" + esc(quote) + '</div>',
      },
      {
        type: 'TEXT', x: 540, y: 1530, width: 800, anchor: 'top-center', track: 4, enterBegin: 1.8, enterEnd: 2.4, enterAnimation: 'fade', exitEnd: quoteSeconds,
        style: { fontFamily: uiFont },
        html: "<div style=\"text-align:center; color:" + paper + "; font-size:34px; font-weight:700; letter-spacing:2px;\">&mdash; " + esc(author) + '</div>',
      },
    ],
  };

  const s2 = {
    id: 'author',
    duration: cardSeconds,
    backgroundColor: ink,
    visuals: [
      { type: 'IMAGE', src: 'https://images.pexels.com/photos/15637846/pexels-photo-15637846.jpeg?auto=compress&cs=tinysrgb&w=1620', width: 1080, height: 1920, position: 'center-center', resize: 'cover', zoom: true, opacity: 0.5, track: 0, enterBegin: 0, exitEnd: cardSeconds },
      {
        type: 'SVG', width: 1080, height: 1920, track: 1, enterBegin: 0, exitEnd: cardSeconds,
        svg: "<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'><defs><linearGradient id='dqrEnd' x1='0' y1='0' x2='0' y2='1'><stop offset='0' stop-color='#14181A' stop-opacity='0.6'/><stop offset='1' stop-color='#14181A' stop-opacity='0.92'/></linearGradient></defs><rect width='1080' height='1920' fill='url(#dqrEnd)'/><circle cx='540' cy='760' r='6' fill='#F0ECE3'/><path d='M420 760 H520 M560 760 H660' stroke='rgba(240,236,227,0.5)' stroke-width='1'/></svg>",
      },
      {
        type: 'TEXT', x: 540, y: 850, width: 860, anchor: 'top-center', track: 2, enterBegin: 0.3, enterEnd: 0.9, enterAnimation: 'smoothup', exitEnd: cardSeconds,
        style: { fontFamily: quoteFont },
        html: "<div style=\"text-align:center; color:" + paper + '; font-size:' + nameSize + "px; font-weight:700;\">" + esc(author) + '</div>',
      },
      {
        type: 'TEXT', x: 540, y: ctaY, anchor: 'top-center', track: 4, enterBegin: 1.1, enterEnd: 1.5, enterAnimation: 'circleopen', exitEnd: cardSeconds,
        style: { fontFamily: uiFont },
        html: "<div style=\"display:inline-block; border:1.5px solid " + paper + '; color:' + paper + "; border-radius:999px; padding:22px 56px; font-size:30px; font-weight:700;\">" + esc(ctaText) + "</div><div style=\"margin-top:16px; text-align:center; color:#7E7A6F; font-size:23px; letter-spacing:5px;\">" + esc(channelName) + '</div>',
      },
    ],
  };
  if (authorNote) {
    s2.visuals.splice(3, 0, {
      type: 'TEXT', x: 540, y: noteY, width: 800, anchor: 'top-center', track: 3, enterBegin: 0.7, enterEnd: 1.2, enterAnimation: 'fade', exitEnd: cardSeconds,
      style: { fontFamily: uiFont },
      html: "<div style=\"text-align:center; color:#A8A396; font-size:27px; font-weight:500; letter-spacing:2px;\">" + esc(authorNote) + '</div>',
    });
  }

  const totalSeconds = round(quoteSeconds + cardSeconds - 0.8);
  // The render API only allows letters, digits, spaces, _ and - in `name`.
  const safeName = ('daily-quote-' + author).toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60);

  const payload = {
    name: safeName || 'Daily quote',
    resolution: 'instagram-reel',
    frameRate: 30,
    backgroundColor: '#1B1E22',
    outputFormat: 'mp4',
    scenes: [s1, s2],
    // NOTE: no `track` here — the render API rejects audios[].track.
    audios: [{ src: musicUrl, volume: Number(cfg.musicVolume ?? 0.15) }],
  };

  return {
    payload,
    meta: {
      poolIndex,
      poolLabel: entry.label,
      bgVideo,
      musicUrl,
      quoteSeconds,
      totalSeconds,
      quoteSize,
      quoteLines,
      quote,
      author,
      quoteChars: qLen,
    },
  };
}

// === n8n glue ===
const config = $('Config').first().json;
const row = $input.first().json;
const built = buildProject(config, { quote: row.quote, author: row.author, authorNote: row.authorNote, date: new Date() });
built.meta.rowNumber = row.rowNumber;
return [{ json: built }];

// The free validate endpoint runs the exact pipeline a render submission runs,
// so a failure here is a payload bug — surface the field list instead of a
// generic HTTP error.
const res = $input.first().json;
const status = res.statusCode;
const body = res.body || {};

if (status !== 200) {
  const details = Array.isArray(body.details)
    ? body.details.map((d) => '  - ' + d.field + ': ' + d.message).join('\n')
    : JSON.stringify(body).slice(0, 500);
  throw new Error('Zvid rejected the project (HTTP ' + status + '): ' + (body.message || body.error) + '\n' + details);
}

const build = $('Build project JSON').first().json;
return [{
  json: {
    ...build,
    creditsRequired: body.creditsRequired,
    warnings: body.warnings || [],
    schemaVersion: body.schemaVersion,
  },
}];

// Fails fast on a failed render and stops the poll loop from running forever.
const cfg = $('Config').first().json;
const job = $input.first().json;

if (job.state === 'failed') {
  throw new Error('Render failed: ' + (job.failedReason || 'no reason given'));
}

const maxPolls = Math.ceil((Number(cfg.timeoutMinutes || 20) * 60) / Number(cfg.pollSeconds || 10));
if ($runIndex + 1 >= maxPolls) {
  throw new Error('Render did not finish within ' + cfg.timeoutMinutes + ' minutes (job ' + job.id + ', state ' + job.state + ').');
}

return $input.all();

// Final report for a live run. By the time this executes the sheet row is
// already marked done with the video URL.
const cfg = $('Config').first().json;
const build = $('Check validation').first().json;
const job = $('Get render status').first().json;
const url = typeof job.result === 'string' ? job.result : (job.result ? job.result.url : null);

return [{
  json: {
    rendered: true,
    videoUrl: url,
    jobId: job.id,
    author: build.meta.author,
    background: build.meta.poolLabel,
    videoSeconds: build.meta.totalSeconds,
    creditsCharged: build.creditsRequired,
    sheetRow: build.meta.rowNumber,
    sheetStatus: cfg.statusDoneValue,
    channel: cfg.channelName,
  },
}];

// Dry run: everything except the paid render. Open editorLink to preview the
// exact video, then set dryRun to false in Config to go live. The sheet row is
// NOT touched on a dry run, so tomorrow's real run picks the same quote.
const cfg = $('Config').first().json;
const d = $('Check validation').first().json;

// The draft save is best-effort (onError: continue) so a hiccup there never
// hides the rest of the dry-run report.
let editorLink = null;
let draftId = null;
try {
  const project = $('Save draft to editor').first().json.project;
  if (project && project.id) {
    draftId = project.id;
    editorLink = String(cfg.editorUrl || 'https://editor.zvid.io').replace(/\/+$/, '') + '/?project=' + project.id;
  }
} catch (e) { /* draft step skipped or failed */ }

return [{
  json: {
    dryRun: true,
    quote: d.meta.quote,
    author: d.meta.author,
    sheetRow: d.meta.rowNumber,
    background: d.meta.poolLabel,
    editorLink,
    draftId,
    creditsRequired: d.creditsRequired,
    videoSeconds: d.meta.totalSeconds,
    warnings: d.warnings,
    sheetUpdated: false,
    nextStep: editorLink
      ? 'Open editorLink to preview the draft, then set dryRun to false in Config to render and mark the row done.'
      : 'Set dryRun to false in Config to render this for real.',
    payload: d.payload,
  },
}];
